from django.conf import settings

settings.configure(INSTALLED_APPS=[], DATABASES={}, USE_I18N=False)

from django.db import models


class FooBar(models.Model):
    foo_bar = models.CharField(max_length=20, choices=((1, 'foo'), (2, 'bar')))

    class Meta:
        app_label = 'repro'

    def __str__(self):
        return self.get_foo_bar_display()

    def get_foo_bar_display(self):
        return 'something'


class Plain(models.Model):
    status = models.CharField(max_length=20, choices=(('x', 'X'), ('y', 'Y')))

    class Meta:
        app_label = 'repro'


class MethodBeforeField(models.Model):
    def get_status_display(self):
        return 'custom-before'

    status = models.CharField(max_length=20, choices=(('x', 'X'), ('y', 'Y')))

    class Meta:
        app_label = 'repro'


assert FooBar(foo_bar=1).get_foo_bar_display() == 'something'
assert str(FooBar(foo_bar=2)) == 'something'
assert Plain(status='x').get_status_display() == 'X'
assert MethodBeforeField(status='x').get_status_display() == 'custom-before'
print('reproduction and edge cases OK')
